// @ts-check
/* ============================================================================
 * rank2.js | Rank 2 Blueprint — documents, viewer, charts, shelf
 * ----------------------------------------------------------------------------
 * The page itself is static HTML so it is readable, indexable and complete
 * without JavaScript. This file only adds the four things static HTML cannot
 * do on a site with no build step at deploy time:
 *
 *   1. Official documents  — read from data/proof-manifest.json (generated by
 *      scripts/proof_documents.py from assets/proof/). A scan dropped in and
 *      published grows a card here; nothing in this page or its markup is
 *      edited to make that happen.
 *   2. The viewer          — a full-screen dialog with zoom, fit, paging,
 *      fullscreen, keyboard, swipe and pinch. PDF.js is fetched only on the
 *      first Preview, so a reader who never opens a document never downloads
 *      a 350 KB renderer.
 *   3. Charts              — drawn from #rbPerf, the same table a reader sees.
 *      One source: the numbers cannot be shown two different ways.
 *   4. Practice + books    — read from the live question index and the book
 *      shelf. No quiz and no book record is written here; this page links to
 *      the ones the other systems already own.
 *
 * Honesty rules, because this is the page they matter most on:
 *   • a slot with no file behind it renders as an explicit "not published yet"
 *     card, never as an empty card and never as a claim;
 *   • nothing is generated, guessed or reconstructed — if a sidecar in
 *     assets/proof/metadata.json carries no question detail, section 7 says so
 *     rather than inventing an answer sheet.
 * ========================================================================== */
(async () => {
  "use strict";

  const { esc } = HOA;
  const $ = (id) => document.getElementById(id);

  /* ------------------------------------------------------------- helpers - */
  const fetchJSON = async (path) => {
    try {
      const r = await fetch(path, { cache: "no-cache" });
      if (!r.ok) return null;
      return await r.json();
    } catch {
      return null;
    }
  };
  const num = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };
  /** 0.9666 → "96.7%" · 1 → "100%" · 0.7 → "70%" (never "70.0%"). */
  const pct = (x) => `${Math.round(x * 1000) / 10}`.replace(/\.0$/, "") + "%";
  const hide = (el) => { if (el) el.hidden = true; };
  const show = (el) => { if (el) el.hidden = false; };
  const pad2 = (n) => (n < 10 ? `0${n}` : String(n));

  /* =========================================================================
   * A. THE ATTEMPT SHEET — one source for totals, charts and every analytics
   *    strip on the page. Read off #rbPerf so a number can never appear here
   *    that is not also in the table a reader can check.
   * ====================================================================== */
  const PERF = (() => {
    const table = $("rbPerf");
    const rows = [];
    if (table) {
      table.querySelectorAll("tbody tr").forEach((tr) => {
        const el = /** @type {HTMLElement} */ (tr);
        rows.push({
          subject: el.getAttribute("data-subject") || "",
          correct: num(el.getAttribute("data-correct")),
          wrong: num(el.getAttribute("data-wrong")),
          skipped: num(el.getAttribute("data-skipped")),
          total: num(el.getAttribute("data-total")),
          paper: el.getAttribute("data-paper") || "",
        });
      });
    }
    const sum = (k) => rows.reduce((a, r) => a + r[k], 0);
    const totals = rows.length
      ? { correct: sum("correct"), wrong: sum("wrong"), skipped: sum("skipped"),
          total: rows.reduce((a, r) => a + r.total, 0) }
      : null;
    if (totals) totals.accuracy = totals.total ? totals.correct / totals.total : 0;

    /* Paper-level roll-up, used by the analytics strip under each answer sheet. */
    const papers = {};
    rows.forEach((r) => {
      if (!r.paper) return;
      const p = (papers[r.paper] = papers[r.paper] ||
        { correct: 0, wrong: 0, skipped: 0, total: 0 });
      p.correct += r.correct; p.wrong += r.wrong;
      p.skipped += r.skipped; p.total += r.total;
    });
    return { rows, totals, papers };
  })();

  /* =========================================================================
   * B. CHARTS — inline SVG, sized by viewBox so they scale to any column
   *    without a charting library, and coloured from the design tokens so the
   *    dark theme reads correctly.
   * ====================================================================== */
  const C = { ok: "#6366f1", bad: "#dc2626", skip: "#f59e0b" };

  const legend = (items) =>
    `<div class="rb-legend">${items
      .map(([col, label]) => `<span><i style="background:${col}"></i>${esc(label)}</span>`)
      .join("")}</div>`;

  function accuracyChart(rows) {
    const W = 360, rowH = 44, H = 6 + rows.length * rowH + 4;
    const bars = rows.map((r, i) => {
      const y = 6 + i * rowH;
      const a = r.total ? r.correct / r.total : 0;
      return (
        `<text x="0" y="${y + 11}" class="c-lab">${esc(r.subject)}</text>` +
        `<rect x="0" y="${y + 17}" width="300" height="15" rx="7.5" style="fill:var(--border)"></rect>` +
        `<rect x="0" y="${y + 17}" width="${(300 * a).toFixed(2)}" height="15" rx="7.5" style="fill:${C.ok}"></rect>` +
        `<text x="310" y="${y + 30}" class="c-val">${pct(a)}</text>`
      );
    }).join("");
    const label = `Accuracy by subject: ${rows
      .map((r) => `${r.subject} ${pct(r.total ? r.correct / r.total : 0)}`)
      .join(", ")}.`;
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label)}">${bars}</svg>`;
  }

  function compareChart(rows) {
    const W = 360, rowH = 46, H = 6 + rows.length * rowH + 4;
    const max = Math.max(...rows.map((r) => r.total), 1);
    const bars = rows.map((r, i) => {
      const y = 6 + i * rowH;
      const full = (W * r.total) / max;
      let x = 0, seg = "";
      /* Correct → wrong → skipped, drawn left to right so the eye reads the
         composition in the same order the table lists it. */
      [["correct", C.ok], ["wrong", C.bad], ["skipped", C.skip]].forEach(([k, col]) => {
        const v = /** @type {any} */ (r)[k];
        if (!v || !full) return;
        const w = (full * v) / r.total;
        seg += `<rect x="${x.toFixed(2)}" y="${y + 16}" width="${w.toFixed(2)}" height="16" style="fill:${col}"></rect>`;
        x += w;
      });
      /* The segments are clipped to the rounded track so the bar keeps one
         clean silhouette instead of a square end poking past a round one. */
      return (
        `<defs><clipPath id="rbcc${i}">` +
        `<rect x="0" y="${y + 16}" width="${full.toFixed(2)}" height="16" rx="8"></rect>` +
        `</clipPath></defs>` +
        `<text x="0" y="${y + 11}" class="c-lab">${esc(r.subject)}</text>` +
        `<text x="${W}" y="${y + 11}" text-anchor="end" class="c-num">${r.correct} · ${r.wrong} · ${r.skipped}</text>` +
        `<rect x="0" y="${y + 16}" width="${full.toFixed(2)}" height="16" rx="8" style="fill:var(--border)"></rect>` +
        `<g clip-path="url(#rbcc${i})">${seg}</g>`
      );
    }).join("");
    const label = `Subject comparison of correct, wrong and skipped answers: ${rows
      .map((r) => `${r.subject} ${r.correct} correct, ${r.wrong} wrong, ${r.skipped} skipped`)
      .join("; ")}.`;
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label)}">${bars}</svg>` +
      legend([[C.ok, "Correct"], [C.bad, "Wrong"], [C.skip, "Skipped"]]);
  }

  function donutChart(t) {
    if (!t) return "";
    const CIRC = 2 * Math.PI * 76;
    const parts = [
      { v: t.correct, col: C.ok, label: "Correct" },
      { v: t.wrong, col: C.bad, label: "Wrong" },
      { v: t.skipped, col: C.skip, label: "Skipped" },
    ];
    let off = 0;
    const arcs = parts.map((p) => {
      const len = (CIRC * p.v) / t.total;
      const s = `<circle cx="115" cy="112" r="76" fill="none" stroke="${p.col}" stroke-width="26" ` +
        `stroke-dasharray="${len.toFixed(2)} ${(CIRC - len).toFixed(2)}" ` +
        `stroke-dashoffset="${(-off).toFixed(2)}"></circle>`;
      off += len;
      return s;
    }).join("");
    const label = `Attempt distribution across ${t.total} questions: ` +
      `${t.correct} correct, ${t.wrong} wrong, ${t.skipped} skipped.`;
    const legendRows = parts.map((p, i) => {
      const y = 74 + i * 40;
      return (
        `<rect x="212" y="${y - 12}" width="13" height="13" rx="3.5" style="fill:${p.col}"></rect>` +
        `<text x="232" y="${y - 1}" class="c-lab">${p.label}</text>` +
        `<text x="232" y="${y + 15}" class="c-num">${p.v} · ${pct(p.v / t.total)}</text>`
      );
    }).join("");
    return (
      `<svg viewBox="0 0 360 232" role="img" aria-label="${esc(label)}">` +
      `<g transform="rotate(-90 115 112)">${arcs}</g>` +
      `<text x="115" y="110" text-anchor="middle" class="c-big">${pct(t.accuracy)}</text>` +
      `<text x="115" y="134" text-anchor="middle" class="c-sub">accuracy</text>` +
      legendRows +
      `</svg>`
    );
  }

  function renderCharts() {
    if (!PERF.rows.length) return;
    const acc = $("rbChartAccuracy");
    const cmp = $("rbChartCompare");
    const don = $("rbChartDonut");
    if (acc) acc.innerHTML = accuracyChart(PERF.rows);
    if (cmp) cmp.innerHTML = compareChart(PERF.rows);
    if (don && PERF.totals) don.innerHTML = donutChart(PERF.totals);
  }

  /* =========================================================================
   * C. DOCUMENT CARDS
   * ====================================================================== */
  let MANIFEST = null;

  function paperStrip(key) {
    if (key === "paper-3") {
      /* Paper 3 is a gate, not a score: the strip states its status instead of
         printing a correct/wrong count the sheet does not carry. */
      return (
        `<dl class="rb-doc-ana rb-doc-ana--words">` +
        `<div><dt>Paper</dt><dd>3</dd></div>` +
        `<div><dt>Subject</dt><dd>Punjabi</dd></div>` +
        `<div><dt>Status</dt><dd>Qualifying</dd></div>` +
        `</dl>`
      );
    }
    const p = PERF.papers[key === "paper-1" ? "Paper 1" : "Paper 2"];
    if (!p) return "";
    return (
      `<dl class="rb-doc-ana">` +
      `<div><dt>Correct</dt><dd class="a-ok">${p.correct}</dd></div>` +
      `<div><dt>Wrong</dt><dd class="a-bad">${p.wrong}</dd></div>` +
      `<div><dt>Skipped</dt><dd class="a-skip">${p.skipped}</dd></div>` +
      `</dl>`
    );
  }

  function docCard(slot) {
    const d = slot.doc;
    const label = esc(slot.label || d.name);
    if (!d) {
      return (
        `<article class="rb-doc is-empty">` +
        `<div class="rb-doc-thumb"><div class="rb-doc-face"><span>Awaiting publication</span></div></div>` +
        `<div class="rb-doc-body">` +
        `<h4 class="rb-doc-title">${label}</h4>` +
        `<p class="rb-doc-waiting">Not published yet</p>` +
        `<p class="rb-doc-note">Nothing published here yet. The card fills itself in — preview,
           download, file type and size — the moment the scan is added.</p>` +
        `</div></article>`
      );
    }
    const isImg = d.kind === "image";
    const thumb = isImg
      ? `<img src="${esc(d.file)}" alt="Preview of ${esc(d.title || d.name)}"
              width="480" height="360" loading="lazy" decoding="async">`
      : `<div class="rb-doc-face"><b>${esc(d.type)}</b><span>${esc(d.size)} · tap to preview</span></div>`;
    const badges =
      `<span class="badge badge-muted">${esc(d.type)}</span>` +
      `<span class="badge badge-muted">${esc(d.size)}</span>` +
      (d.uploaded ? `<span class="badge badge-muted">${esc(d.uploaded)}</span>` : "");
    const ana = slot.analytics ? paperStrip(slot.analytics) : "";
    return (
      `<article class="rb-doc">` +
      `<div class="rb-doc-thumb">${thumb}<span class="rb-doc-badge">${isImg ? "Image" : "PDF"}</span></div>` +
      `<div class="rb-doc-body">` +
      `<h4 class="rb-doc-title">${esc(d.title || slot.label)}</h4>` +
      (d.note ? `<p class="rb-doc-note">${esc(d.note)}</p>` : "") +
      `<div class="rb-doc-meta">${badges}</div>` +
      `<div class="rb-doc-actions">` +
      `<button type="button" class="btn btn-primary btn-sm" data-preview="${esc(d.file)}">Preview</button>` +
      `<a class="btn btn-soft btn-sm" href="${esc(d.file)}" download>Download</a>` +
      `</div></div>` + ana + `</article>`
    );
  }

  function renderDocs() {
    const grid = $("rbDocGrid");
    if (!grid || !MANIFEST) return;
    const slots = Array.isArray(MANIFEST.slots) ? MANIFEST.slots : [];
    grid.innerHTML = slots.map(docCard).join("");
    if (num(MANIFEST.total) > 0) hide($("rbDocPending")); else show($("rbDocPending"));
    grid.querySelectorAll("[data-preview]").forEach((b) => {
      b.addEventListener("click", () => {
        const file = b.getAttribute("data-preview") || "";
        const slot = slots.find((s) => s.doc && s.doc.file === file);
        if (slot && slot.doc) openDoc(slot.doc, b);
      });
    });
  }

  /* =========================================================================
   * D. ORIGINAL ANSWER SHEET ANALYSIS (section 7)
   *    Cards exist only for a sheet that really carries question detail in its
   *    sidecar. Nothing is reconstructed, so an absent explanation stays
   *    absent instead of being written to look complete.
   * ====================================================================== */
  function questionRow(q, i) {
    const sel = q.selected == null ? "" : String(q.selected);
    const cor = q.correct == null ? "" : String(q.correct);
    const wrong = !!(sel && cor && sel !== cor);
    const head =
      `<div class="rb-q-head"><span class="rb-q-n">Q${q.n == null ? i + 1 : esc(String(q.n))}</span>` +
      (q.text ? `<p class="rb-q-t">${esc(String(q.text))}</p>` : "") +
      `</div>`;
    const chips =
      (sel ? `<span class="rb-q-opt ${wrong ? "is-wrong" : "is-right"}">Selected · ${esc(sel)}</span>` : "") +
      (cor ? `<span class="rb-q-opt is-right">Correct · ${esc(cor)}</span>` : "");
    return (
      `<li class="rb-q">${head}` +
      (chips ? `<div class="rb-q-opts">${chips}</div>` : "") +
      (q.explanation ? `<p class="rb-q-exp">${esc(String(q.explanation))}</p>` : "") +
      `</li>`
    );
  }

  function sheetCard(slot) {
    const d = slot.doc;
    const qs = (d && Array.isArray(d.questions)) ? d.questions : [];
    if (!d || !qs.length) return "";
    const perf = PERF.papers[slot.analytics === "paper-2" ? "Paper 2" : "Paper 1"];
    return (
      `<article class="card card-pad rb-sheet">` +
      `<div class="rb-sheet-top">` +
      `<span class="badge">${esc(slot.label)}</span>` +
      `<span class="rb-mistake-n">${qs.length} question${qs.length === 1 ? "" : "s"} published</span>` +
      `</div>` +
      `<h3>${esc(d.title || slot.label)}</h3>` +
      (perf
        ? `<p class="rb-doc-note">Sheet totals: ${perf.correct} correct, ${perf.wrong} wrong,
             ${perf.skipped} skipped across ${perf.total} questions.</p>`
        : "") +
      `<div class="btn-row">` +
      `<button type="button" class="btn btn-primary btn-sm" data-preview="${esc(d.file)}">Preview sheet</button>` +
      `<a class="btn btn-soft btn-sm" href="${esc(d.file)}" download>Download</a>` +
      `</div>` +
      `<details class="rb-sheet-qs"><summary><span>${qs.length} questions — selected vs correct</span></summary>` +
      `<ol class="rb-qlist">${qs.map(questionRow).join("")}</ol>` +
      `</details></article>`
    );
  }

  function renderSheets() {
    const host = $("rbSheets");
    if (!host || !MANIFEST) return;
    const slots = Array.isArray(MANIFEST.slots) ? MANIFEST.slots : [];
    const cards = slots
      .filter((s) => s.analytics && s.doc && Array.isArray(s.doc.questions) && s.doc.questions.length)
      .map(sheetCard)
      .filter(Boolean);
    if (!cards.length) { host.innerHTML = ""; show($("rbSheetsEmpty")); return; }
    host.innerHTML = cards.join("");
    hide($("rbSheetsEmpty"));
    host.querySelectorAll("[data-preview]").forEach((b) => {
      b.addEventListener("click", () => {
        const file = b.getAttribute("data-preview") || "";
        const slot = slots.find((s) => s.doc && s.doc.file === file);
        if (slot && slot.doc) openDoc(slot.doc, b);
      });
    });
  }

  /* =========================================================================
   * E. VIEWER — one dialog, two renderers (PDF.js and <img>).
   * ====================================================================== */
  const PDFJS_BASE = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/";
  let pdfLibP = null;
  const loadPdfLib = () => {
    if (!pdfLibP) {
      const p = new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = `${PDFJS_BASE}pdf.min.js`;
        s.async = true;
        s.onload = () => {
          const lib = /** @type {any} */ (window).pdfjsLib;
          if (!lib) { reject(new Error("pdf.js did not register")); return; }
          lib.GlobalWorkerOptions.workerSrc = `${PDFJS_BASE}pdf.worker.min.js`;
          resolve(lib);
        };
        s.onerror = () => reject(new Error("pdf.js could not be downloaded"));
        document.head.appendChild(s);
      });
      /* Drop the failed promise so the next Preview retries instead of
         caching a network hiccup for the whole session. */
      p.catch(() => { pdfLibP = null; });
      pdfLibP = p;
    }
    return /** @type {Promise<any>} */ (pdfLibP);
  };

  const V = {
    doc: /** @type {any} */ (null),
    pdf: /** @type {any} */ (null),
    baseW: 0, baseH: 0,
    scale: 1,
    page: 1,
    renderToken: 0,
    trigger: /** @type {HTMLElement|null} */ (null),
  };

  const el = {
    root: /** @type {HTMLElement|null} */ ($("rbViewer")),
    stage: /** @type {HTMLElement|null} */ ($("rbvStage")),
    canvas: /** @type {HTMLCanvasElement|null} */ ($("rbvCanvas")),
    img: /** @type {HTMLImageElement|null} */ ($("rbvImg")),
    spin: $("rbvSpin"), msg: $("rbvMsg"), type: $("rbViewerType"), title: $("rbViewerTitle"),
    page: /** @type {HTMLInputElement|null} */ ($("rbvPage")), pages: $("rbvPages"),
    zoom: $("rbvZoom"), prev: $("rbvPrev"), next: $("rbvNext"),
    dl: /** @type {HTMLAnchorElement|null} */ ($("rbvDl")),
    swipe: $("rbvSwipe"),
  };

  const busy = (on) => {
    if (on) show(el.spin); else hide(el.spin);
  };
  const note = (html) => {
    if (!el.msg) return;
    el.msg.innerHTML = html;
    show(el.msg);
    hide(el.canvas); hide(el.img); busy(false);
  };
  const updateChrome = () => {
    const d = V.doc;
    const one = !d || d.kind !== "pdf";
    if (el.zoom) el.zoom.textContent = `${Math.round(V.scale * 100)}%`;
    if (el.pages) el.pages.textContent = one ? "1" : String((V.pdf && V.pdf.numPages) || 1);
    if (el.page) {
      el.page.value = String(V.page);
      el.page.max = one ? "1" : String((V.pdf && V.pdf.numPages) || 1);
      el.page.disabled = one;
    }
    if (el.prev) /** @type {any} */ (el.prev).disabled = one || V.page <= 1;
    if (el.next) /** @type {any} */ (el.next).disabled =
      one || (!!V.pdf && V.page >= V.pdf.numPages);
    if (el.swipe) el.swipe.hidden = one;
  };

  const fitScale = (mode) => {
    if (!V.baseW || !V.baseH || !el.stage) return 1;
    const sw = el.stage.clientWidth - 8;
    const sh = el.stage.clientHeight - 8;
    const byW = sw / V.baseW, byH = sh / V.baseH;
    let s = mode === "width" ? byW : Math.min(byW, byH);
    /* A raster scan blown up past 2× stops being legible rather than
       becoming larger, so fit never runs away on a small image. */
    if (V.doc && V.doc.kind !== "pdf") s = Math.min(s, 2);
    return Math.max(0.05, s);
  };

  const setScale = (s, rerender) => {
    V.scale = Math.min(8, Math.max(0.1, s));
    if (V.doc && V.doc.kind !== "pdf" && el.img && !el.img.hidden) {
      el.img.style.width = `${Math.round(V.baseW * V.scale)}px`;
      el.img.style.height = "auto";
    } else if (rerender !== false) {
      renderPDF();
    }
    updateChrome();
  };

  let renderTimer = 0;
  function renderPDF() {
    const pdf = V.pdf, cv = el.canvas;
    if (!pdf || !V.doc || V.doc.kind !== "pdf" || !cv) return;
    window.clearTimeout(renderTimer);
    const token = ++V.renderToken;
    renderTimer = window.setTimeout(async () => {
      try {
        const page = await pdf.getPage(V.page);
        if (token !== V.renderToken) return;
        const vp = page.getViewport({ scale: V.scale });
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        cv.width = Math.max(1, Math.floor(vp.width * dpr));
        cv.height = Math.max(1, Math.floor(vp.height * dpr));
        cv.style.width = `${Math.floor(vp.width)}px`;
        cv.style.height = `${Math.floor(vp.height)}px`;
        hide(el.img); show(cv); busy(false);
        const ctx = cv.getContext("2d");
        if (!ctx) return;
        await page.render({ canvasContext: ctx, viewport: vp, transform: dpr !== 1 ? [dpr, 0, 0, dpr, 0, 0] : undefined })
          .promise;
      } catch (err) {
        if (token === V.renderToken) {
          const file = V.doc ? V.doc.file : "";
          note(`This page could not be rendered. ` +
            `<a href="${esc(file)}" download>Download the file</a> instead.`);
        }
      }
    }, 120);
  }

  async function openDoc(d, trigger) {
    if (!el.root || !el.stage) return;
    V.doc = d; V.pdf = null; V.page = 1; V.scale = 1;
    V.baseW = 0; V.baseH = 0;
    V.trigger = trigger instanceof HTMLElement ? trigger : null;
    if (el.title) el.title.textContent = d.title || d.name || "Document";
    if (el.type) el.type.textContent = d.type || "FILE";
    if (el.dl) { el.dl.href = d.file; el.dl.setAttribute("download", d.name || ""); }
    hide(el.msg); hide(el.canvas); hide(el.img);
    el.root.hidden = false;
    document.body.classList.add("rbv-open");
    updateChrome();
    busy(true);
    el.stage.focus();

    if (d.kind === "pdf") {
      try {
        const lib = await loadPdfLib();
        V.pdf = await lib.getDocument({ url: d.file }).promise;
        hide(el.spin);
        const page0 = await V.pdf.getPage(1);
        const vp0 = page0.getViewport({ scale: 1 });
        V.baseW = vp0.width; V.baseH = vp0.height;
        setScale(fitScale("page"));
        updateChrome();
      } catch (err) {
        note(`The preview engine could not be loaded
              (it needs a network connection the first time).
              <a href="${esc(d.file)}" download>Download the file</a> to read it.`);
      }
    } else {
      try {
        await new Promise((res, rej) => {
          const img = el.img;
          if (!img) { rej(new Error("no img")); return; }
          img.alt = d.title || d.name || "Document";
          img.onload = () => res(null);
          img.onerror = () => rej(new Error("image failed"));
          img.src = d.file;
        });
        V.baseW = el.img.naturalWidth || 900;
        V.baseH = el.img.naturalHeight || 1200;
        el.img.style.width = `${Math.round(V.baseW * V.scale)}px`;
        hide(el.spin); hide(el.msg); show(el.img);
        setScale(fitScale("page"), false);
        updateChrome();
      } catch (err) {
        note(`This image could not be displayed.
              <a href="${esc(d.file)}" download>Download it</a> instead.`);
      }
    }
  }

  function closeViewer() {
    if (!el.root || el.root.hidden) return;
    el.root.hidden = true;
    document.body.classList.remove("rbv-open");
    V.renderToken++;
    V.doc = null; V.pdf = null;
    if (el.img) { el.img.onload = null; el.img.onerror = null; el.img.removeAttribute("src"); }
    if (el.canvas) el.canvas.getContext("2d") && el.canvas.getContext("2d").clearRect(0, 0, el.canvas.width, el.canvas.height);
    if (document.fullscreenElement) { document.exitFullscreen().catch(() => {}); }
    const t = V.trigger;
    V.trigger = null;
    if (t && document.contains(t)) t.focus();
  }

  function goPage(n) {
    if (!V.pdf) return;
    const max = V.pdf.numPages || 1;
    const p = Math.min(max, Math.max(1, Math.round(n)));
    if (p === V.page) { updateChrome(); return; }
    V.page = p;
    busy(true);
    renderPDF();
    updateChrome();
    if (el.stage) el.stage.scrollTop = 0;
  }

  const on = (id, type, fn) => {
    const node = document.getElementById(id);
    if (node) node.addEventListener(type, fn);
  };

  const wireViewer = () => {
    const root = el.root, pageInput = el.page;
    if (!root) return;
    on("rbvClose", "click", closeViewer);
    on("rbvIn", "click", () => setScale(V.scale * 1.25));
    on("rbvOut", "click", () => setScale(V.scale / 1.25));
    on("rbvWidth", "click", () => setScale(fitScale("width")));
    on("rbvFit", "click", () => setScale(fitScale("page")));
    on("rbvPrev", "click", () => goPage(V.page - 1));
    on("rbvNext", "click", () => goPage(V.page + 1));
    if (pageInput) pageInput.addEventListener("change", () => goPage(num(pageInput.value)));
    on("rbvFull", "click", toggleFullscreen);
    /* Clicking the dialog's own chrome, never the document, is what closes it:
       the stage fills the rest of the viewport, so a stray drag cannot. */
    root.addEventListener("mousedown", (e) => { if (e.target === root) closeViewer(); });

    window.addEventListener("resize", () => {
      if (root && !root.hidden && V.doc) updateChrome();
    });
  };

  function toggleFullscreen() {
    const root = el.root;
    if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
    else if (root && root.requestFullscreen) root.requestFullscreen().catch(() => {});
  }

  const wireKeys = () => {
    const root = el.root, dl = el.dl;
    if (!root) return;
    document.addEventListener("keydown", (e) => {
      if (root.hidden) return;
      const t = /** @type {HTMLElement} */ (e.target);
      const typing = t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable);
      if (e.key === "Escape") { e.preventDefault(); closeViewer(); return; }
      if (typing) return;
      switch (e.key) {
        case "ArrowRight": case "PageDown": e.preventDefault(); goPage(V.page + 1); break;
        case "ArrowLeft": case "PageUp": e.preventDefault(); goPage(V.page - 1); break;
        case "Home": e.preventDefault(); goPage(1); break;
        case "End": e.preventDefault(); goPage(V.pdf ? V.pdf.numPages : 1); break;
        case "+": case "=": case "ArrowUp": e.preventDefault(); setScale(V.scale * 1.25); break;
        case "-": case "_": case "ArrowDown": e.preventDefault(); setScale(V.scale / 1.25); break;
        case "0": e.preventDefault(); setScale(fitScale("page")); break;
        case "1": case "2": e.preventDefault(); setScale(fitScale("width")); break;
        case "f": case "F": e.preventDefault(); toggleFullscreen(); break;
        case "s": case "S":
          if (dl && dl.href) { e.preventDefault(); dl.click(); }
          break;
        default: break;
      }
    });
  };

  /* Touch: vertical scroll stays native (touch-action: pan-y), pinch changes
     the scale, a horizontal drag pans a zoomed page, and a horizontal flick
     turns the page when the document fits the stage. */
  const wireTouch = () => {
    const stage = el.stage;
    if (!stage) return;
    const pts = new Map();
    let start = null, pinch0 = 0, scale0 = 1, panning = false, lastX = 0;

    stage.addEventListener("touchstart", (e) => {
      for (let i = 0; i < e.touches.length; i++) {
        const t = e.touches[i];
        pts.set(t.identifier, { x: t.clientX, y: t.clientY });
      }
      if (e.touches.length === 2) {
        const [a, b] = [e.touches[0], e.touches[1]];
        pinch0 = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
        scale0 = V.scale;
        start = null;
      } else if (e.touches.length === 1) {
        const t = e.touches[0];
        start = { x: t.clientX, y: t.clientY, t: Date.now() };
        lastX = t.clientX;
        panning = stage.scrollWidth > stage.clientWidth + 2;
      }
    }, { passive: true });

    stage.addEventListener("touchmove", (e) => {
      if (e.touches.length === 2 && pinch0) {
        const [a, b] = [e.touches[0], e.touches[1]];
        const d = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
        if (d > 0) { e.preventDefault(); setScale(scale0 * (d / pinch0)); }
        return;
      }
      if (e.touches.length === 1 && panning && start) {
        const t = e.touches[0];
        stage.scrollLeft -= t.clientX - lastX;
        lastX = t.clientX;
        if (Math.abs(t.clientX - start.x) > 8) e.preventDefault();
      }
    }, { passive: false });

    stage.addEventListener("touchend", (e) => {
      for (let i = 0; i < e.changedTouches.length; i++) pts.delete(e.changedTouches[i].identifier);
      if (e.touches.length < 2) pinch0 = 0;
      if (e.touches.length === 0 && start && V.pdf && V.pdf.numPages > 1 && !panning) {
        const t = e.changedTouches[0];
        const dx = t.clientX - start.x, dy = t.clientY - start.y;
        const dt = Date.now() - start.t;
        /* A flick, not a drag: fast, one-directional and clearly horizontal. */
        if (dt < 700 && Math.abs(dx) > 46 && Math.abs(dx) > Math.abs(dy) * 1.6) {
          goPage(dx < 0 ? V.page + 1 : V.page - 1);
        }
      }
      start = null; panning = false;
    }, { passive: true });
  };

  /* =========================================================================
   * F. PRACTICE QUESTIONS — the live quiz index, grouped by the subjects this
   *    page actually discusses. No question is written or stored here.
   * ====================================================================== */
  const DISCUSSED = ["gk", "quant", "reasoning", "punjabi", "english", "computer", "current-affairs"];
  const quizHref = (subjectId, t) =>
    `quiz.html?subject=${encodeURIComponent(subjectId)}&topic=${encodeURIComponent(t.id)}` +
    (t.category ? `&category=${encodeURIComponent(t.category)}` : "");

  async function renderPractice() {
    const host = $("rbQuiz");
    if (!host) return;
    const idx = await HOA.loadIndex();
    const subjects = (idx && Array.isArray(idx.subjects) ? idx.subjects : [])
      .filter((s) => DISCUSSED.indexOf(s.id) >= 0);
    if (!subjects.length) return;
    host.innerHTML = subjects.map((s) => {
      const topics = Array.isArray(s.topics) ? s.topics : [];
      const qs = topics.reduce((a, t) => a + num(t.count), 0);
      const rows = topics.slice(0, 6).map((t) =>
        `<li><a href="${quizHref(s.id, t)}"><span class="t">${esc(t.name)}</span>` +
        `<span class="n">${num(t.count)} Q</span></a></li>`).join("");
      const more = topics.length > 6
        ? `<p class="rb-empty-note">+ ${topics.length - 6} more sets on
             <a class="ilink" href="practice.html">Practice</a>.</p>` : "";
      const empty = topics.length
        ? ""
        : `<p class="rb-empty-note">Sets for this subject are being added on
             <a class="ilink" href="practice.html">Practice</a>.</p>`;
      return (
        `<div class="card card-pad rb-grp">` +
        `<div class="rb-grp-top"><h3>${esc(s.name)}</h3>` +
        `<span class="badge badge-muted">${topics.length} set${topics.length === 1 ? "" : "s"}` +
        (qs ? ` · ${qs} Q` : "") + `</span></div>` +
        (rows ? `<ul class="rb-quizlinks">${rows}</ul>` : "") + more + empty +
        `<div class="btn-row"><a class="btn btn-soft btn-sm" href="practice.html">Open subject practice</a></div>` +
        `</div>`
      );
    }).join("");
  }

  /* =========================================================================
   * G. BOOKS — the real shelf, opened three ways per card.
   * ====================================================================== */
  async function renderBooks() {
    const host = $("rbBooks");
    if (!host) return;
    const data = await fetchJSON("data/books.json");
    const books = data && Array.isArray(data.books)
      ? data.books.filter((b) => DISCUSSED.indexOf(b.subject) >= 0)
      : [];
    if (!books.length) return;
    host.innerHTML = books.map((b) => {
      const rating = num(b.rating);
      return (
        `<article class="card card-pad rb-book">` +
        `<div class="rb-book-top">` +
        `<span class="badge badge-muted">${esc(b.subjectLabel || b.subject || "")}</span>` +
        (rating ? `<span class="rb-book-rate">★ ${rating.toFixed(1)}</span>` : "") +
        `</div>` +
        `<h3>${esc(b.title)}</h3>` +
        (b.author ? `<p class="rb-book-auth">${esc(b.author)}</p>` : "") +
        (b.description ? `<p class="rb-book-desc">${esc(b.description)}</p>` : "") +
        `<div class="btn-row">` +
        `<a class="btn btn-primary btn-sm" href="book-${encodeURIComponent(b.id)}.html">Open Book</a>` +
        `<a class="btn btn-soft btn-sm" href="study.html?subject=${encodeURIComponent(b.subject)}">Open Notes</a>` +
        (b.subject
          ? `<a class="btn btn-soft btn-sm" href="quiz.html?mode=mock&subject=${encodeURIComponent(b.subject)}">Open Quiz</a>`
          : "") +
        `</div></article>`
      );
    }).join("");
  }

  /* =========================================================================
   * H. DEEP LINKS — #timetable and friends land on a collapsed card, so open
   *    the card the hash points at instead of scrolling to an invisible box.
   * ====================================================================== */
  const openHashTarget = () => {
    const id = (location.hash || "").replace(/^#/, "");
    if (!id) return;
    const node = document.getElementById(id);
    if (!node) return;
    const d = node.tagName === "DETAILS" ? /** @type {HTMLElement} */ (node)
      : node.closest("details");
    if (d) d.setAttribute("open", "");
  };

  /* ---------------------------------------------------------------- boot -- */
  wireViewer(); wireKeys(); wireTouch();
  renderCharts();
  openHashTarget();
  window.addEventListener("hashchange", openHashTarget);

  MANIFEST = await fetchJSON("data/proof-manifest.json");
  if (MANIFEST) { renderDocs(); renderSheets(); }

  /* Practice, books and the shelf are independent, so one failing to load
     must not take the others down with it. */
  renderPractice().catch(() => {});
  renderBooks().catch(() => {});
})();
